package com.app.entity;
import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Table(name="society_work_assignments") @Data @Builder @NoArgsConstructor @AllArgsConstructor
public class SocietyWorkAssignment {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="account_id",nullable=false) private Account account; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="work_order_id",nullable=false) private SocietyWorkOrder workOrder; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="staff_id") private SocietyStaff staff; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="agency_id") private SocietyAgency agency; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="vendor_id") private Supplier vendor; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="assigned_by_user_id",nullable=false) private User assignedBy; @Column(nullable=false,updatable=false) @Builder.Default private LocalDateTime assignedAt=LocalDateTime.now(); @Column(nullable=false) @Builder.Default private Boolean active=true;}
